function actionButton(text,attributes){return `<button type="button" data-pw-write ${attributes}>${text}</button>`}
function options(map,selected){return Object.entries(map).map(([value,label])=>`<option value="${attr(value)}"${String(selected)===value?' selected':''}>${esc(label)}</option>`).join('')}
function selectMarkup(id,label,map,value){return `<label for="${id}">${label}<select id="${id}">${options(map,value)}</select></label>`}
const tabQueues={waiting:'Новые',mine:'Мои',all:'Все открытые',closed:'Закрытые'};
const tabChannels={max:'MAX',telegram:'Telegram',website:'Сайт'};
function tabValues(tab,key,legacy){if(Array.isArray(tab?.[key]))return [...tab[key]];const value=tab?.[legacy];return value?[value]:[]}
function tabEditorValues(tab){return {...tab,queues:Array.isArray(tab.queues)?[...tab.queues]:[tab.queue||'all'],channels:tabValues(tab,'channels','channel'),source_ids:tabValues(tab,'source_ids','source_id'),label_ids:tabValues(tab,'label_ids','label_id')}}
function tabQueue(tab){const values=Array.isArray(tab?.queues)?tab.queues:[tab?.queue||'all'];return values.length===1?values[0]:'all'}
