  $('pwTabEditor').onsubmit=event=>{event.preventDefault();capture();if(!tabDraft.queues.length){setStatus('Выберите хотя бы одну очередь.',true);$('pwTabQueue').querySelector('details').open=true;$('pwTabQueueChoicewaiting')?.focus();return}const {id,queue,channel,source_id,label_id,...tab}=tabDraft;void mutate('tab_save',{id:Number(id||0),tab},'tab')};
