function renderLabels(){const box=$('pwLabels');if(!box)return;box.innerHTML=`<div class="pwSectionHead"><h3>Мои метки</h3>${actionButton('+ Метка','id="pwNewLabel"')}</div><p>Один клиент может входить в несколько ваших подборок.</p><div class="pwRows">${ordinaryLabels().map(l=>`<div class="pwRow"><strong>${esc(l.name)}</strong><div class="pwRowActions">${actionButton('Изменить',`data-pw-edit-label="${l.id}"`)}${actionButton('Удалить',`data-pw-delete-label="${l.id}"`)}</div></div>`).join('')||(ready?'<p class="pwEmpty">Метки пока не созданы.</p>':'<p class="pwEmpty">Настройки ещё не загружены.</p>')}</div>${labelDraft?`<form id="pwLabelEditor" class="pwEditor"><label for="pwLabelName">Название метки<input id="pwLabelName" maxlength="64" required value="${attr(labelDraft.name)}"></label><div class="pwEditorActions"><button id="pwLabelSave" data-pw-write type="submit">Сохранить метку</button><button id="pwLabelCancel" type="button">Отмена</button></div></form>`:''}`;$('pwNewLabel').onclick=()=>beginLabel();box.querySelectorAll('[data-pw-edit-label]').forEach(b=>b.onclick=()=>beginLabel(b.dataset.pwEditLabel));box.querySelectorAll('[data-pw-delete-label]').forEach(b=>b.onclick=()=>{if(window.confirm('Удалить только вашу метку и её отметки? Клиенты и диалоги останутся.'))void mutate('label_delete',{id:Number(b.dataset.pwDeleteLabel)})});if(labelDraft){$('pwLabelName').addEventListener('input',()=>{labelDraft={...labelDraft,name:$('pwLabelName').value};draftRevision++;persist()});$('pwLabelEditor').onsubmit=e=>{e.preventDefault();void mutate('label_save',{id:Number(labelDraft.id||0),name:labelDraft.name},'label')};$('pwLabelCancel').onclick=()=>{if(busy||pending)return;labelDraft=null;persist();renderLabels();$('pwNewLabel')?.focus()}}updateBusy()}
function renderClient(){const box=$('pwClient');if(!box)return;const focus=focusTarget();const c=S.detail?.conversation,valid=current>0&&Number(S.current)===current&&Number(c?.id)===current;box.hidden=!valid;if(!valid){box.innerHTML='';return}const pinned=state.pins.some(id=>Number(id)===current);box.innerHTML=`<h3>Мои отметки: ${esc(c.display_name||'Клиент')}</h3><p>Личные отметки не меняют ответственного менеджера.</p>${actionButton(pinned?'Открепить':'Закрепить у меня',`id="pwPin" aria-pressed="${pinned}"`)}<div class="pwClientLabels">${ordinaryLabels().map(l=>`<label class="pwCheck"><input data-pw-write data-pw-membership="${l.id}" type="checkbox" ${(state.members[String(l.id)]||[]).some(id=>Number(id)===current)?'checked':''}>${esc(l.name)}</label>`).join('')||'<p class="pwEmpty">Создайте метку ниже, чтобы отметить этого клиента.</p>'}</div>`;const captured=current;$('pwPin').onclick=()=>mutate('pin',{conversation_id:captured,enabled:!pinned});box.querySelectorAll('[data-pw-membership]').forEach(b=>b.onchange=()=>{const enabled=b.checked;renderClient();void mutate('label_membership',{conversation_id:captured,label_id:Number(b.dataset.pwMembership),enabled})});updateBusy();restoreFocus(focus)}
